import{_ as e,o as s,c as o,ag as r}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"CNS Master 模块教学文档","titleTemplate":false,"description":"","frontmatter":{"title":"CNS Master 模块教学文档","titleTemplate":false,"pageClass":"docs-home"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),l={name:"index.md"};function n(t,a,i,h,p,d){return s(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="cns-master-模块教学文档" tabindex="-1">CNS Master 模块教学文档 <a class="header-anchor" href="#cns-master-模块教学文档" aria-label="Permalink to &quot;CNS Master 模块教学文档&quot;">​</a></h1><p class="home-lead">从通信、导航与监视原理到实验接线，<br class="home-lead-break">一步步搭建、运行与观察。</p><p>这里收录模块原理、端口与参数说明，以及可以直接打开的实验工程。选择与你使用的 Master 版本一致的文档，从一个信号源开始探索。</p><div class="home-actions"><a class="home-button primary" href="./v0.3.0-alpha/learn/">开始阅读</a></div><p><strong>v0.3.0-alpha 已发布</strong>。安装包通过产品交付渠道提供；对应版本源码与构建说明向软件接收者提供。</p><p>历史版本文档保留原下载链接，是否能够访问取决于原仓库权限。当前使用者请从产品交付渠道获取安装包。</p><h2 id="开始一次本地实验" tabindex="-1">开始一次本地实验 <a class="header-anchor" href="#开始一次本地实验" aria-label="Permalink to &quot;开始一次本地实验&quot;">​</a></h2><p>纯软件实验在 PC 本地运行，无需实验箱或账号。没有通信基础时，从<a href="./v0.3.0-alpha/learn/">低空通信、导航与监视学习路径</a>按顺序做短实验；需要查询某个模块时再读手册。</p><ol><li><strong>先理解问题</strong> — 从<a href="./v0.3.0-alpha/learn/01-link-overview/">状态回传的链路全貌</a>开始，再认识幅度、频率和采样。</li><li><strong>打开示例</strong> — 下载文章中的 <code>.cnsproj</code>，在 Master 的“文件 → 打开工程”载入。</li><li><strong>运行并观察</strong> — 按 <strong>F5</strong> 运行，在观察器中比较时域信号与频谱；按 <strong>Shift+F5</strong> 停止。</li></ol><h2 id="按主题学习" tabindex="-1">按主题学习 <a class="header-anchor" href="#按主题学习" aria-label="Permalink to &quot;按主题学习&quot;">​</a></h2><div class="home-topics"><section><h3 id="信号与-i-q" tabindex="-1">信号与 I/Q <a class="header-anchor" href="#信号与-i-q" aria-label="Permalink to &quot;信号与 I/Q&quot;">​</a></h3><p>从实数波形、噪声到复数信号，理解频率、幅度与 I/Q 分量。</p><p><a href="./v0.3.0-alpha/modules/signal_source/">信号源</a> · <a href="./v0.3.0-alpha/modules/complex_signal_source/">复数信号源</a> · <a href="./v0.3.0-alpha/modules/iq_split/">I/Q 分解</a></p></section><section><h3 id="运算与滤波" tabindex="-1">运算与滤波 <a class="header-anchor" href="#运算与滤波" aria-label="Permalink to &quot;运算与滤波&quot;">​</a></h3><p>比较增益、延时与频率选择，观察信号经过处理后的变化。</p><p><a href="./v0.3.0-alpha/modules/gain/">增益</a> · <a href="./v0.3.0-alpha/modules/delay/">延时</a> · <a href="./v0.3.0-alpha/modules/low_pass/">低通滤波</a></p></section><section><h3 id="符号与星座" tabindex="-1">符号与星座 <a class="header-anchor" href="#符号与星座" aria-label="Permalink to &quot;符号与星座&quot;">​</a></h3><p>连接码元源、映射器和判决器，观察索引与复数星座的关系。</p><p><a href="./v0.3.0-alpha/modules/random_symbols/">随机码元</a> · <a href="./v0.3.0-alpha/modules/symbol_mapper/">符号映射</a> · <a href="./v0.3.0-alpha/modules/symbol_slicer/">符号判决</a></p></section><section><h3 id="向量与标签" tabindex="-1">向量与标签 <a class="header-anchor" href="#向量与标签" aria-label="Permalink to &quot;向量与标签&quot;">​</a></h3><p>从点表构造输入，区分 item、向量分量与流标签的含义。</p><p><a href="./v0.3.0-alpha/modules/vector_source/">向量点表源</a> · <a href="./v0.3.0-alpha/modules/delay/">延时与标签</a></p></section><section><h3 id="距离与位置" tabindex="-1">距离与位置 <a class="header-anchor" href="#距离与位置" aria-label="Permalink to &quot;距离与位置&quot;">​</a></h3><p>从无人机到三个锚点的距离，理解平面坐标怎样解算出来。</p><p><a href="./v0.3.0-alpha/modules/coordinate_source/">坐标发生器</a> · <a href="./v0.3.0-alpha/modules/range_simulator/">测距模拟器</a> · <a href="./v0.3.0-alpha/modules/position_solver_2d/">二维定位解算器</a></p></section><section><h3 id="相关与延迟测距" tabindex="-1">相关与延迟测距 <a class="header-anchor" href="#相关与延迟测距" aria-label="Permalink to &quot;相关与延迟测距&quot;">​</a></h3><p>移动参考序列，找到延迟，再把样本数换算成秒和米。</p><p><a href="./v0.3.0-alpha/modules/correlator/">相关器</a> · <a href="./v0.3.0-alpha/modules/peak_detector/">峰值检测器</a> · <a href="./v0.3.0-alpha/modules/range_estimator/">测距器</a></p></section></div><h2 id="选择文档版本" tabindex="-1">选择文档版本 <a class="header-anchor" href="#选择文档版本" aria-label="Permalink to &quot;选择文档版本&quot;">​</a></h2><p>文章、参数和下载工程随 Master 版本组织。旧版本入口会继续保留。</p><div class="home-versions"><a class="home-version" href="./v0.3.0-alpha/"><span class="home-version-name">v0.3.0-alpha<span class="home-version-status">已发布</span></span><span class="home-version-detail">37 类模块 · 10 个示例工程</span><span class="home-version-link">进入文档 <span aria-hidden="true">→</span></span></a><a class="home-version" href="./v0.2.0-alpha/"><span class="home-version-name">v0.2.0-alpha<span class="home-version-status">已发布</span></span><span class="home-version-detail">31 类模块 · 7 个示例工程</span><span class="home-version-link">进入文档 <span aria-hidden="true">→</span></span></a><a class="home-version" href="./v0.1.0-alpha/"><span class="home-version-name">v0.1.0-alpha<span class="home-version-status">已发布</span></span><span class="home-version-detail">27 类模块 · 5 个示例工程</span><span class="home-version-link">进入文档 <span aria-hidden="true">→</span></span></a></div><p>从左侧目录查找模块，也可以使用顶部搜索。进入模块文章后，右侧“本页内容”可快速定位接线、参数和常见问题。</p>',15)])])}const v=e(l,[["render",n]]);export{m as __pageData,v as default};
